# this code is generated by chatgpt to measure how much of a speedup and memory saving
# can be achieved by using Automatic Mixed Precision (AMP) in PyTorch
import torch
import torch.nn as nn
import torch.optim as optim
import torchvision
import torchvision.transforms as transforms
import time
import gc

# ---------- Setup ----------
device = torch.device("cuda" if torch.cuda.is_available() else "cpu")

# Transform and dataset
transform = transforms.Compose([
    transforms.ToTensor(),
    transforms.Normalize((0.5,), (0.5,))
])
train_loader = torch.utils.data.DataLoader(
    torchvision.datasets.CIFAR10(root='./data', train=True, download=True, transform=transform),
    batch_size=128, shuffle=True
)

# ---------- Model ----------
class SimpleCNN(nn.Module):
    def __init__(self):
        super().__init__()
        self.net = nn.Sequential(
            nn.Conv2d(3, 32, 3, padding=1), nn.ReLU(), nn.MaxPool2d(2),
            nn.Conv2d(32, 64, 3, padding=1), nn.ReLU(), nn.MaxPool2d(2),
            nn.Flatten(),
            nn.Linear(64 * 8 * 8, 128), nn.ReLU(),
            nn.Linear(128, 10)
        )
    def forward(self, x):
        return self.net(x)

# ---------- Training Loop ----------
def train(model, loader, use_amp=False):
    model = model.to(device)
    criterion = nn.CrossEntropyLoss()
    optimizer = optim.Adam(model.parameters(), lr=1e-3)

    scaler = torch.cuda.amp.GradScaler() if use_amp else None

    torch.cuda.reset_peak_memory_stats()
    start = time.time()

    for inputs, targets in loader:
        inputs, targets = inputs.to(device), targets.to(device)
        optimizer.zero_grad()

        if use_amp:
            with torch.cuda.amp.autocast():
                outputs = model(inputs)
                loss = criterion(outputs, targets)
            scaler.scale(loss).backward()
            scaler.step(optimizer)
            scaler.update()
        else:
            outputs = model(inputs)
            loss = criterion(outputs, targets)
            loss.backward()
            optimizer.step()

    torch.cuda.synchronize()  # wait for all kernels to finish
    end = time.time()
    mem = torch.cuda.max_memory_allocated(device) / (1024**2)  # in MB

    return end - start, mem

# ---------- Benchmark ----------
print("\n🔁 Running standard FP32 training...")
fp32_model = SimpleCNN()
fp32_time, fp32_mem = train(fp32_model, train_loader, use_amp=False)

gc.collect()
torch.cuda.empty_cache()

print("\n⚡ Running mixed precision training (AMP)...")
amp_model = SimpleCNN()
amp_time, amp_mem = train(amp_model, train_loader, use_amp=True)

# ---------- Report ----------
print("\n📊 Benchmark Results:")
print(f"FP32 time: {fp32_time:.2f}s, memory: {fp32_mem:.2f} MB")
print(f"AMP  time: {amp_time:.2f}s, memory: {amp_mem:.2f} MB")

speedup = fp32_time / amp_time
mem_saving = (fp32_mem - amp_mem) / fp32_mem * 100

print(f"\n🚀 Speedup with AMP: {speedup:.2f}x faster")
print(f"💾 Memory saving with AMP: {mem_saving:.2f}% less memory")
